mapper.select:
SELECT id, data_name, data_type, data_subtype, security_level, data_version, source_system, description, status, uploader, department, upload_time, character_count, summary, attachment_path, attachment_name, created_at, updated_at FROM data_elements
AND data_name LIKE CONCAT('%', #{dataName}, '%')
AND data_type = #{dataType}
AND data_subtype LIKE CONCAT('%', #{dataSubtype}, '%')
AND security_level = #{securityLevel}
AND department LIKE CONCAT('%', #{department}, '%')
AND status = #{status}
ORDER BY upload_time DESC
